 static Transform Find(Transform root,string path){foreach(string c in path.Split('/')){if(c.Length==0)continue;int i=c.LastIndexOf(':');string name=c.Substring(0,i);int n=int.Parse(c.Substring(i+1));Transform? found=null;for(int j=0;j<root.childCount;j++){var child=root.GetChild(j);if(child.name==name&&n--==0){found=child;break;}}if(found==null)throw new Exception("Native authored path missing "+path);root=found;}return root;}
