ow.SetActive(true);var a=Object.Instantiate(achievement.gameObject,s.Manager.resultsPanel.transform,false);a.name="OriginalAchievement"+i;a.SetActive(true);}
  foreach(var g in s.Root.GetComponentsInChildren<CanvasGroup>(true))g.alpha=1;
